CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, details jsonb NOT NULL DEFAULT '{}'::jsonb, onboarding_step integer NOT NULL DEFAULT 0 CHECK (onboarding_step BETWEEN 0 AND 5), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile read" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY "Own profile insert" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_customer_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES (NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER create_customer_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_customer_profile();
CREATE TABLE public.customer_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id), available_balance numeric(18,2) NOT NULL DEFAULT 0 CHECK (available_balance = 0), current_balance numeric(18,2) NOT NULL DEFAULT 0 CHECK (current_balance = 0), status text NOT NULL DEFAULT 'Active' CHECK (status = 'Active'), opened_at timestamptz NOT NULL DEFAULT now(), terms_version text NOT NULL, privacy_version text NOT NULL, identity_consent_at timestamptz NOT NULL);
GRANT SELECT ON public.customer_accounts TO authenticated;
GRANT ALL ON public.customer_accounts TO service_role;
ALTER TABLE public.customer_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own account read" ON public.customer_accounts FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.customer_security (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), pin_hash text NOT NULL, question_ids text[] NOT NULL, answer_hashes text[] NOT NULL, biometric_preference boolean NOT NULL DEFAULT false);
GRANT ALL ON public.customer_security TO service_role;
ALTER TABLE public.customer_security ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.complete_customer_onboarding(p_pin_hash text, p_question_ids text[], p_answer_hashes text[], p_biometric boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE account_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF array_length(p_question_ids, 1) <> 3 OR array_length(p_answer_hashes, 1) <> 3 OR length(p_pin_hash) < 80 THEN RAISE EXCEPTION 'Invalid security data'; END IF; IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = auth.uid() AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Confirm your email first'; END IF; IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND onboarding_step = 5) THEN RAISE EXCEPTION 'Complete your application first'; END IF; INSERT INTO public.customer_security VALUES (auth.uid(), p_pin_hash, p_question_ids, p_answer_hashes, p_biometric) ON CONFLICT (user_id) DO NOTHING; INSERT INTO public.customer_accounts(user_id, terms_version, privacy_version, identity_consent_at) VALUES (auth.uid(), 'onboarding-notice-2026-10', 'privacy-notice-2026-10', now()) ON CONFLICT (user_id) DO NOTHING; SELECT id INTO account_id FROM public.customer_accounts WHERE user_id = auth.uid(); RETURN account_id; END; $$;
REVOKE ALL ON FUNCTION public.complete_customer_onboarding(text,text[],text[],boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.complete_customer_onboarding(text,text[],text[],boolean) TO authenticated;